return {
    ts: ctx.latestTs,
    values: {
        fuelConsumptionRate: getConsumptionRate()
    }
};


function getConsumptionRate() {
    if (fuelLevel.count() < 2) {
        return 0;
    }
    var first = fuelLevel.first();
    var last = fuelLevel.last();


    if (isNaN(first) || isNaN(last)) {
        return 0;
    }

    var deltaLevelPercentage = first - last;
    if (deltaLevelPercentage <= 0) {
        return 0;
    }
    var fuelTankCapacity = 86.6; // gal (345 L)
    var fuelConsumptionRate = (deltaLevelPercentage / 100.0) * fuelTankCapacity;
    return toFixed(fuelConsumptionRate, 2);
}
